using FolderVerse;using Microsoft.Xna.Framework;using Microsoft.Xna.Framework.Graphics;using Microsoft.Xna.Framework.Input;using System.Reflection;
using var game=new SpectatingUi(args[0]);game.Run();
sealed class SpectatingUi(string output):Game1{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;WorldSetup w=null!;SpriteBatch batch=null!;
 object Get(string n)=>typeof(Game1).GetField(n,F)!.GetValue(this)!;void Set(string n,object v)=>typeof(Game1).GetField(n,F)!.SetValue(this,v);object Call(string n,params object[] a)=>typeof(Game1).GetMethod(n,F)!.Invoke(this,a)!;
 void Check(bool ok,string m){if(!ok)throw new Exception(m);Console.WriteLine("PASS "+m);} protected override void LoadContent(){Window.Position=new(-3000,-3000);AppContext.SetData("APP_CONTEXT_BASE_DIRECTORY",Environment.GetEnvironmentVariable("GAME_RUNTIME"));w=new(){EquipmentMode=RobotEquipmentMode.Materials};w.SetParticipantCounts(1,1);w.SetWorld(1);w.SetCast(2);w.SetPlacement(3);w.Relations.Reset();w.SelectPlayer(0);w.Relations.Leader=0;w.Robots.Initialize(w.Nodes.All.Length,w.ActiveCount);w.Robots.ConfigureFactories(w);w.Salvage.Reset();w.Salvage.EnableExpeditions(w);foreach(var n in w.Nodes.All)n.Owner=0;int h=w.Nodes.All.First(n=>n.Functional).Id;w.ConquerorLocations[0]=w.Nodes.All[h].Cell;w.ConquerorPoints[0]=w.Nodes.All[h].Center;
 foreach(var material in Enum.GetValues<RobotMaterial>()){var robot=w.Robots.Create(0,RobotParts.Complete,RobotRole.Captain) with{HeadMaterial=material,BodyMaterial=(RobotMaterial)(((int)material+1)%9),LegsMaterial=material};w.Robots.Nodes[h].Add(robot);var good=w.Robots.Create(1,RobotParts.Complete) with{HeadMaterial=material,BodyMaterial=material,LegsMaterial=material,IntegratedParts=(int)material%2==0?RobotParts.Head|RobotParts.Body:0};w.Salvage.Items.Add(new(1000+(int)material,h,good));}
 Set("_setup",w);batch=new(GraphicsDevice);var pixel=new Texture2D(GraphicsDevice,1,1);pixel.SetData(new[]{Color.White});Set("_spriteBatch",batch);Set("_pixel",pixel);Content.RootDirectory=Path.Combine(Environment.GetEnvironmentVariable("OLD_RUNTIME")!,"Content");Set("_portraitRenderer",new PortraitRenderer(Content));var fonts=new Microsoft.Xna.Framework.Content.ContentManager(Services,Path.Combine(Environment.GetEnvironmentVariable("PROBE_FONT")!,"Content"));var font=fonts.Load<SpriteFont>("UiFont");Set("_font",font);Set("_ui",Activator.CreateInstance(typeof(Game1).GetField("_ui",F)!.FieldType,batch,pixel,font)!);Set("_conquestAudioUnavailable",true);Set("_screen",Enum.Parse(Get("_screen").GetType(),"WorldStatus")); Set("_counter",new ToyCounterRenderer(font,pixel));Set("_world",new WorldPreview(GraphicsDevice));
 w.SetHumanPlayer(0,true);Check(w.HasSurvivingHumanController,"living human keeps manual play");w.Relations.Pending.Add(new Captive(0,1,h));Check(w.HasSurvivingHumanController,"pending captive is not prematurely game over");w.Relations.Pending.Clear();
 w.SetHumanPlayer(1,true);w.Relations.Powered[0]=false;Check(w.HasSurvivingHumanController,"another human remains playable");w.Relations.Powered[1]=false;Check(!w.HasSurvivingHumanController&&w.TurnPlayers().Length==0,"batteryless humans have no turn");
 Call("UpdateGameOverSpectating");Check((bool)Get("_autoPlay"),"game over starts automatic spectator play");Check((string)typeof(Game1).GetProperty("AutomaticLabel",F)!.GetValue(this)! =="Game Over","spectator label is Game Over");
 Call("UpdateAutoPlay",.5d,false,false,1d);Check((double)Get("_autoDomesticAge")>.4,"spectator advances without a click");Call("AutoPauseInput",true,false);Check((bool)Get("_autoPaused"),"spectator can pause via click");Call("ResumeAutoPause");Check(!(bool)Get("_autoPaused"),"spectator resumes");
 w.Relations.RestoreBattery(w,1);Call("UpdateGameOverSpectating");Check(!(bool)Get("_autoPlay")&&w.PlayerSlot==1,"restored human regains manual play");
 w.SetHumanPlayer(1,false);w.SetHumanPlayer(0,false);Check(w.ComputerOnly,"zero human configuration is exhibition");Check((string)typeof(Game1).GetProperty("AutomaticLabel",F)!.GetValue(this)! =="Exhibition","computer-only label stays Exhibition");
 w.SetHumanPlayer(0,true);w.Relations.Powered[0]=false;Call("UpdateGameOverSpectating");Set("_autoAge",1d);
 }
